  'inimigos.txt':
    '# As ondas de pedras do Atirador Espacial.\n# Cada linha é uma pedra: segundos, imagem, x, velocidade, vida\n#   segundos: quando ela aparece, contando do começo da onda\n#   imagem: pedra_pequena, pedra_media ou pedra_grande\n#   x: onde ela aparece, de 0 (esquerda) a 800 (direita)\n#   velocidade: quanto ela desce a cada quadro\n#   vida: quantos tiros ela aguenta\n# A linha com "fim" diz em que segundo a onda acaba (pedra marcada depois disso não\n# aparece). Aí a onda recomeça, mais rápida.\n0.5, pedra_pequena, 200, 3, 1\n1.0, pedra_pequena, 600, 3, 1\n1.8, pedra_media, 400, 2, 2\n2.5, pedra_pequena, 120, 4, 1\n2.5, pedra_pequena, 680, 4, 1\n3.4, pedra_grande, 300, 1.5, 3\n4.2, pedra_media, 550, 2.5, 2\n5.0, pedra_pequena, 250, 4, 1\n5.0, pedra_pequena, 450, 4, 1\n5.8, pedra_grande, 650, 1.5, 3\n6.6, pedra_media, 150, 3, 2\n7.2, pedra_pequena, 400, 5, 1\n8.0, pedra_media, 700, 2.5, 2\n8.0, pedra_media, 100, 2.5, 2\n9.0, pedra_grande, 400, 2, 3\n12, fim\n',
